+        Media(search: \$search, type: ANIME) {
+          id
+          siteUrl
+          title { romaji english native }
+          description(asHtml: false)
+          episodes
+          coverImage { large medium }
+          bannerImage
+          startDate { year month day }
+        }
+      }
+      ''';
+
+      final variables = { 'search': title ?? '' };
