+  Future<T> schedule<T>(Future<T> Function() fn) {
+    final completer = Completer<T>();
+    _queue.add(_QueuedCall(fn, completer as Completer<Object?>));
+    if (!_running) _processQueue();
+    return completer.future as Future<T>;
+  }
